def bulk_batch_size(self, fields, objs):
    """
    Return the maximum allowed batch size for the backend. The fields
    are the fields going to be inserted in the batch, the objs contains
    all the objects to be inserted.
    """
    if self.connection.features.max_query_params is None or not fields:
        return len(objs)

    return self.connection.features.max_query_params // len(
        list(
            chain.from_iterable(
                field.fields if isinstance(field, CompositePrimaryKey) else [field]
                for field in fields
            )
        )
    )

def configure_settings(self, databases):
    databases = super().configure_settings(databases)
    if databases == {}:
        databases[DEFAULT_DB_ALIAS] = {"ENGINE": "django.db.backends.dummy"}
    elif DEFAULT_DB_ALIAS not in databases:
        raise ImproperlyConfigured(
            f"You must define a '{DEFAULT_DB_ALIAS}' database."
        )
    elif databases[DEFAULT_DB_ALIAS] == {}:
        databases[DEFAULT_DB_ALIAS]["ENGINE"] = "django.db.backends.dummy"

    # Configure default settings.
    for conn in databases.values():
        conn.setdefault("ATOMIC_REQUESTS", False)
        conn.setdefault("AUTOCOMMIT", True)
        conn.setdefault("ENGINE", "django.db.backends.dummy")
        if conn["ENGINE"] == "django.db.backends." or not conn["ENGINE"]:
            conn["ENGINE"] = "django.db.backends.dummy"
        conn.setdefault("CONN_MAX_AGE", 0)
        conn.setdefault("CONN_HEALTH_CHECKS", False)
        conn.setdefault("OPTIONS", {})
        conn.setdefault("TIME_ZONE", None)
        for setting in ["NAME", "USER", "PASSWORD", "HOST", "PORT"]:
            conn.setdefault(setting, "")

        test_settings = conn.setdefault("TEST", {})
        default_test_settings = [
            ("CHARSET", None),
            ("COLLATION", None),
            ("MIGRATE", True),
            ("MIRROR", None),
            ("NAME", None),
        ]
        for key, value in default_test_settings:
            test_settings.setdefault(key, value)
    return databases

@property
def pool(self):
    pool_options = self.settings_dict["OPTIONS"].get("pool")
    if self.alias == NO_DB_ALIAS or not pool_options:
        return None

    if self.alias not in self._connection_pools:
        if self.settings_dict.get("CONN_MAX_AGE", 0) != 0:
            raise ImproperlyConfigured(
                "Pooling doesn't support persistent connections."
            )
        # Set the default options.
        if pool_options is True:
            pool_options = {}

        try:
            from psycopg_pool import ConnectionPool
        except ImportError as err:
            raise ImproperlyConfigured(
                "Error loading psycopg_pool module.\nDid you install psycopg[pool]?"
            ) from err

        connect_kwargs = self.get_connection_params()
        # Ensure we run in autocommit, Django properly sets it later on.
        connect_kwargs["autocommit"] = True
        enable_checks = self.settings_dict["CONN_HEALTH_CHECKS"]
        # Copy to avoid mutating the user's settings dict.
        pool_options = {**pool_options}
        pool_options.setdefault(
            "check", ConnectionPool.check_connection if enable_checks else None
        )
        pool = ConnectionPool(
            kwargs=connect_kwargs,
            open=False,  # Do not open the pool during startup.
            configure=self._configure_connection,
            **pool_options,
        )
        # setdefault() ensures that multiple threads don't set this in
        # parallel. Since we do not open the pool during its init above,
        # this means that at worst during startup multiple threads generate
        # pool objects and the first to set it wins.
        self._connection_pools.setdefault(self.alias, pool)

    return self._connection_pools[self.alias]

